#include <metal_stdlib>
using namespace metal;

struct Uniforms {
    float4x4 MVP;
    float4 OutputSize;
    float4 SourceSize;
    float4 OriginalSize;
    uint FrameCount;
    // Noir base
    float noir_contrast;    // 0..3
    float noir_exposure;    // -2..2 stops
    float edge_softness;    // 0..2
    // Neon layer
    float neon_threshold;   // 0..1
    float neon_strength;    // 0..3
    float hue_shift;        // -1..1 cycles
    float glow_radius;      // 1..10 px
};

struct VIn { float4 pos [[attribute(0)]]; float2 uv [[attribute(1)]]; };
struct VOut { float4 pos [[position]]; float2 uv; };

vertex VOut main0(VIn in [[stage_in]], constant Uniforms &u [[buffer(0)]]) {
    VOut o; o.pos = u.MVP * in.pos; o.uv = in.uv; return o;
}

static inline float3 rgb2hsv(float3 c){
    float4 K = float4(0.0, -1.0/3.0, 2.0/3.0, -1.0);
    float4 p = mix(float4(c.bg, K.wz), float4(c.gb, K.xy), step(c.b, c.g));
    float4 q = mix(float4(p.xyw, c.r), float4(c.r, p.yzx), step(p.x, c.r));
    float d = q.x - min(q.w, q.y); float e = 1.0e-10;
    return float3(abs(q.z + (q.w - q.y) / (6.0*d + e)), d/(q.x+e), q.x);
}
static inline float3 hsv2rgb(float3 c){
    float4 K = float4(1.0, 2.0/3.0, 1.0/3.0, 3.0);
    float3 p = abs(fract(c.xxx + K.xyz) * 6.0 - K.www);
    return c.z * mix(K.xxx, clamp(p - K.xxx, 0.0, 1.0), c.y);
}

fragment float4 fragment_main(VOut in [[stage_in]], texture2d<float> src [[texture(0)]], constant Uniforms &u [[buffer(0)]]) {
    constexpr sampler s(address::clamp_to_edge, filter::linear);
    float2 texel = 1.0 / u.OutputSize.xy;
    float3 c0 = src.sample(s, in.uv).rgb;

    // Noir base (high contrast mono)
    float L = dot(c0, float3(0.2126,0.7152,0.0722));
    L = L * pow(2.0, u.noir_exposure);
    L = saturate((L - 0.5) * max(0.0, u.noir_contrast) + 0.5);

    // Soft edge enhancement
    float gx=0.0, gy=0.0;
    float kx[9] = {-1,0,1,-2,0,2,-1,0,1};
    float ky[9] = {-1,-2,-1,0,0,0,1,2,1};
    int idx=0; for(int j=-1;j<=1;++j){ for(int i=-1;i<=1;++i){
        float3 s3 = src.sample(s, in.uv + float2(i,j)*texel).rgb;
        float Ll = dot(s3, float3(0.2126,0.7152,0.0722));
        gx += Ll * kx[idx]; gy += Ll * ky[idx]; idx++; }}
    float edge = smoothstep(0.0, 1.0, length(float2(gx,gy))*0.5);
    float noir = clamp(L + edge * u.edge_softness * 0.25, 0.0, 1.0);

    // Neon bright pass + small blur
    int r = int(clamp(u.glow_radius, 1.0, 10.0));
    float3 acc = float3(0.0); float wsum = 0.0;
    for (int y=-r; y<=r; ++y){ for (int x=-r; x<=r; ++x){
        float2 o = float2(x,y); float w = exp(-dot(o,o)/max(1.0,float(r)));
        float3 s3 = src.sample(s, in.uv + o*texel).rgb;
        float lum = dot(s3, float3(0.2126,0.7152,0.0722));
        float bp = max(0.0, lum - u.neon_threshold);
        acc += s3 * (bp*w); wsum += (bp*w);
    }}
    float3 glow = (wsum>0.0)? acc/wsum : float3(0.0);

    // Hue shift
    float3 hsv = rgb2hsv(glow);
    hsv.x = fract(hsv.x + u.hue_shift);
    float3 neon = hsv2rgb(hsv);

    float3 outc = float3(noir);
    outc = saturate(outc + neon * u.neon_strength);
    return float4(outc, 1.0);
}

